<script lang="ts">
import {objectProps} from '$lib/elements';
import {getFiles,getProjects,getTotals,projectSlug} from '@awc-ui/showcase-kit/design';
import Screen from '$lib/screens/Screen.svelte';
import ChoiceTabs from '$lib/editor/ChoiceTabs.svelte';
import SelectControl from '$lib/editor/SelectControl.svelte';
import StudioDialog from '$lib/editor/StudioDialog.svelte';
import TextControl from '$lib/editor/TextControl.svelte';
import {route} from '$lib/routes';
import {TEMPLATES,ORB_ART,documentSvg,makeTemplate} from '@awc-ui/pictor-model';
import {document} from '$lib/document'; import {t} from '$lib/showcase'; import {navigate} from '$lib/router'; import Link from '$lib/components/Link.svelte';
let query: any = ''; const setQuery = (value: any) => query = typeof value === "function" ? value(query) : value;
let filter: any = 'all'; const setFilter = (value: any) => filter = typeof value === "function" ? value(filter) : value;
let sort: any = 'recent'; const setSort = (value: any) => sort = typeof value === "function" ? value(sort) : value;
let view: any = 'grid'; const setView = (value: any) => view = typeof value === "function" ? value(view) : value;
let template: any = null; const setTemplate = (value: any) => template = typeof value === "function" ? value(template) : value;
let favorites: any = (() => { try { const value = JSON.parse(localStorage.getItem('pictor:favorites') || '[]'); return Array.isArray(value) ? value.filter(item => typeof item === 'string') : []; } catch { return []; } })(); const setFavorites = (value: any) => favorites = typeof value === "function" ? value(favorites) : value;
$: totals = getTotals();
$: projects = getProjects();
$: files = (() => getFiles().filter(file =>
    (!query || `${file.name} ${projects.find(project => project.id === file.projectId)?.name ?? ''}`.toLowerCase().includes(query.toLowerCase())) &&
    (filter === 'all' || filter === 'favorites' && favorites.includes(file.id) || filter === 'shared' && file.editorHandles.length > 1),
  ).slice().sort((a, b) => sort === 'name' ? a.name.localeCompare(b.name) : sort === 'layers' ? $document.layersForFile(b.id).length - $document.layersForFile(a.id).length : b.updatedAt.localeCompare(a.updatedAt)))();
$: toggleFavorite = (id: string) => setFavorites(current => { const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id]; try { localStorage.setItem('pictor:favorites', JSON.stringify(next)); } catch {} return next; });
$: selectedTemplate = template ? makeTemplate(template) : null;
</script>
<Screen title={$t('Your creative workspace')} subtitle={$t('A little structure. Infinite possibility.')}> <section class="pictor-hero" aria-label={$t('Welcome to Pictor')}> <div class="pictor-hero__copy"> <span class="pictor-eyebrow"><span class="pictor-live-dot"></span> {$t('MADE FOR YOUR NEXT BIG IDEA')}</span> <h2>{$t('Big ideas.')}<br /><em>{$t('Beautifully made.')}</em></h2> <p>{$t('From the first spark to the final pixel. Draw, compose, refine and export in one beautifully connected studio.')}</p> <div class="pictor-hero__actions"><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="filled" icon="draw" on:click={() => navigate(route.editor())}>{$t('Enter the studio')}</md-button><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="text" icon="auto_awesome" on:click={() => window.document.getElementById('pictor-templates')?.scrollIntoView({ behavior: 'smooth', block: 'start' })}>{$t('Start with a spark')}</md-button></div> <div class="pictor-hero__facts"><span><strong>{totals.projects}</strong> {$t('creative spaces')}</span><span><strong>{totals.assets}</strong> {$t('reusable assets')}</span><span><strong>{$t('Yours.')}</strong> {$t('Saved on this device')}</span></div> </div> <div class="pictor-hero__art" aria-hidden="true"><div class="pictor-art-orbit"></div><img src={ORB_ART.src} alt="" /><span class="pictor-art-label pictor-art-label--top"><span class="material-symbols-outlined" aria-hidden="true">deployed_code</span> {$t('Shape the unexpected')}</span><span class="pictor-art-label pictor-art-label--bottom"><span class="pictor-live-dot"></span> {$t('Boundless by design')}</span></div> </section> <section id="pictor-templates" class="pictor-section"> <div class="pictor-section__head"><div><span class="pictor-eyebrow">{$t('SKIP THE BLANK CANVAS')}</span><h2>{$t('A starting point. A world of possibilities.')}</h2></div><span class="pictor-muted">{$t('Every layer is yours to change')}</span></div> <div class="pictor-template-grid">{#each TEMPLATES as item}<button class="pictor-template" data-template={item.id} on:click={() => setTemplate(item.id)}><div class="pictor-template__art" data-tone={item.tone}><img src={item.art.src} alt="" /><span>{$t(item.tagline)}</span><span class="pictor-template__arrow"><span class="material-symbols-outlined" aria-hidden="true">arrow_outward</span></span></div><div class="pictor-template__meta"><strong>{$t(item.name)}</strong><span>{$t(item.category)} · 960 × 640</span></div></button>{/each}</div> </section> <section class="pictor-section"> <div class="pictor-section__head"><div><span class="pictor-eyebrow">{$t('ROOM TO CREATE')}</span><h2>{$t('Your projects')}</h2></div><span class="pictor-muted">{projects.length} {$t('spaces, one creative flow')}</span></div> <div class="pictor-project-grid">{#each projects as project, index}<Link href={route.project(projectSlug(project))} class="pictor-project-card"><div class="pictor-project-mark" data-tone={TEMPLATES[index % 3].tone}><span class="material-symbols-outlined" aria-hidden="true">{['shapes', 'photo_camera', 'auto_awesome', 'view_quilt', 'palette', 'architecture'][index % 6]}</span></div><div><strong>{project.name}</strong><span>{project.fileIds.length} {$t('design files')}</span></div><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></Link>{/each}</div> </section> <section class="pictor-section"> <div class="pictor-section__head"><h2>{$t('Pick up where inspiration left you')}</h2><ChoiceTabs label={$t('File layout')} value={view} onValue={setView} options={[{ value: 'grid', label: $t('Grid'), icon: 'grid_view' }, { value: 'list', label: $t('List'), icon: 'view_list' }]}></ChoiceTabs></div> <div class="pictor-filterbar"><md-button-group variant="connected" selection-mode="single-select" required aria-label={$t('Filter design files')} use:objectProps={{selectionMode:'single-select',required:true}} on:mdSelectionChange={event=>{if(event.detail.values[0])setFilter(event.detail.values[0])}}>
<md-button value="all" variant="tonal" use:objectProps={{selected:filter==='all'}}>{$t('All files')}</md-button>
<md-button value="favorites" icon="star" variant="tonal" use:objectProps={{selected:filter==='favorites'}}>{$t('Starred')}</md-button>
<md-button value="shared" icon="group" variant="tonal" use:objectProps={{selected:filter==='shared'}}>{$t('Shared')}</md-button>
</md-button-group><TextControl live label={$t('Search files')} placeholder={$t('Find your next idea…')} value={query} onValue={setQuery}></TextControl><SelectControl label={$t('Sort by')} value={sort} onValue={setSort} options={[{ value: 'recent', label: $t('Recently edited') }, { value: 'name', label: $t('Name') }, { value: 'layers', label: $t('Most layers') }]}></SelectControl></div> {#if files.length}<div class="pictor-file-grid" data-view={view}>{#each files as file}<md-card class="pictor-file-card" variant="outlined"><Link href={route.file(file.id)} class="pictor-file-preview" aria-label={$t('Open {name}', {name: file.name})}><img src={`data:image/svg+xml,${encodeURIComponent(documentSvg($document.layersForFile(file.id), $t))}`} alt={$t('{name} canvas preview', {name: file.name})} loading="lazy" /><span class="pictor-open-label"><span class="material-symbols-outlined" aria-hidden="true">open_in_new</span> {$t('Open canvas')}</span></Link><div class="pictor-file-meta"><Link href={route.file(file.id)}><strong>{file.name}</strong><span>{projects.find(project => project.id === file.projectId)?.name} · {$document.layersForFile(file.id).length} {$t('layers')}</span></Link><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-icon-button icon={favorites.includes(file.id) ? 'star' : 'star_outline'} aria-label={`${favorites.includes(file.id) ? $t('Unstar') : $t('Star')} ${file.name}`} on:click={() => toggleFavorite(file.id)}></md-icon-button></div><div class="pictor-file-footer"><md-chip label={$t(file.stateKey)}></md-chip><span><span class="material-symbols-outlined" aria-hidden="true">group</span> {file.editorHandles.length}</span></div></md-card>{/each}</div>{:else}<div class="pictor-empty"><span class="material-symbols-outlined" aria-hidden="true">search_off</span><h3>{$t('No files in this view')}</h3><p>{$t('Try another search or star a design to collect it here.')}</p><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="text" on:click={() => { setQuery(''); setFilter('all'); }}>{$t('Show all files')}</md-button></div>{/if} </section> <StudioDialog open={!!template} onClose={() => setTemplate(null)} title={selectedTemplate ? $t(selectedTemplate.name) : $t('Choose a template')}> {#if selectedTemplate}<img class="pictor-template-preview" src={`data:image/svg+xml,${encodeURIComponent(documentSvg(selectedTemplate.layers))}`} alt={$t('{name} editable design', {name: $t(selectedTemplate.name)})} /><p>{$t('This replaces your current canvas with')} {selectedTemplate.layers.length} {$t('editable layers. You can undo the replacement from the studio history.')}</p>{/if} <svelte:fragment slot="actions"><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="text" on:click={() => setTemplate(null)}>{$t('Keep exploring')}</md-button><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="filled" icon="auto_awesome" on:click={() => { if (selectedTemplate) {
    $document.replaceCanvas(selectedTemplate.layers);
    setTemplate(null);
    navigate(route.editor());
} }}>{$t('Make it yours')}</md-button></svelte:fragment></StudioDialog> <svelte:fragment slot="aside"><!-- AWC owns keyboard activation inside its shadow control. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-static-element-interactions -->
<md-button variant="tonal" icon="arrow_outward" on:click={() => navigate(route.editor())}>{$t('Resume designing')}</md-button></svelte:fragment></Screen>
